// Copied from AudioCaps v1.0.0 (commit 049d053) crates/audiocaps-ffi/src/lib.rs; renamed (ac_ to
// dc_), the audio-only calls (can_play, active probe, CEC, software codecs) are dropped, the
// display scope and options are used and a manual watch trigger is added.
//! DisplayCaps C ABI (`libdisplaycaps.so`, header `include/displaycaps.h`, generated by cbindgen).
//!
//! Design:
//! - Opaque handles: [`DcContext`] (a probe context: system root, probe thread, generations),
//!   [`DcSnapshot`] (an immutable result; queries take no locks and do no I/O) and [`DcWatch`].
//! - Scope, options and results are JSON in the published schema
//!   (`schema/displaycaps-snapshot-v1.schema.json`); `NULL` scope means everything, `NULL` options
//!   the defaults (passive, per-backend deadlines, redaction on, no opt-ins).
//! - Strings returned as `char *` are owned by the caller: free them with [`dc_string_free`].
//!   Strings returned as `const char *` are borrowed from the handle they came from.
//! - Errors: functions return `NULL` (or a negative number) and set a thread-local message read
//!   with [`dc_last_error`].
//! - Events: [`dc_watch_new`] delivers a new snapshot and its diff for the watched scope, either on
//!   an internal thread ([`DC_WATCH_THREAD`]) or through a pollable fd and [`dc_watch_dispatch`] on
//!   the application's own thread (for Qt or GLib loops). A watch re-probes when the application
//!   calls [`dc_watch_trigger`] or every `watch_interval_ms`; event sources of its own arrive with
//!   the backends.
//!
//! This is the only crate that uses `unsafe`; it holds no logic beyond marshalling.

#![allow(unsafe_code)]

use std::cell::RefCell;
use std::collections::VecDeque;
use std::ffi::{CStr, CString, c_char, c_int, c_void};
use std::os::fd::{AsRawFd, OwnedFd};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

use displaycaps_backends::watch::Trigger;
use displaycaps_backends::{ProbeOptions, Runtime, SystemRoot};
use displaycaps_model::{
    ContentRequest, EndpointClass, EndpointId, FieldGroup, LayerKind, PresentationPath, ProbeScope,
    RedactionPolicy, Selection, Snapshot,
};
use serde::Deserialize;

/// ABI version: bumped on any incompatible change to the functions in this header.
pub const DC_ABI_VERSION: u32 = 1;

/// Watch mode: the callback runs on an internal thread.
pub const DC_WATCH_THREAD: u32 = 1;
/// Watch mode: the callback runs from [`dc_watch_dispatch`] on the caller's thread; poll the fd
/// from [`dc_watch_fd`] for readability.
pub const DC_WATCH_DISPATCH: u32 = 0;

/// Dispatch mode keeps at most this many undelivered updates.
const MAX_PENDING: usize = 32;

thread_local! {
    static LAST_ERROR: RefCell<CString> = RefCell::new(CString::default());
}

fn set_error(msg: impl Into<String>) {
    let s = CString::new(msg.into().replace('\0', " ")).unwrap_or_default();
    LAST_ERROR.with(|e| *e.borrow_mut() = s);
}

/// A probe context.
pub struct DcContext {
    rt: Runtime,
}

/// An immutable snapshot.
pub struct DcSnapshot {
    snap: Arc<Snapshot>,
    ids: Vec<CString>,
}

impl DcSnapshot {
    fn new(snap: Arc<Snapshot>) -> Self {
        let ids = snap
            .endpoints
            .iter()
            .map(|e| CString::new(e.id.0.replace('\0', " ")).unwrap_or_default())
            .collect();
        Self { snap, ids }
    }
}

/// Watch callback: `snapshot` and `diff_json` are borrowed for the duration of the call; keep the
/// snapshot with [`dc_snapshot_clone`].
pub type DcWatchCallback = Option<
    unsafe extern "C" fn(user: *mut c_void, snapshot: *const DcSnapshot, diff_json: *const c_char),
>;

struct Pending {
    queue: Mutex<VecDeque<(Arc<Snapshot>, CString)>>,
}

/// A watch.
pub struct DcWatch {
    stop: Arc<AtomicBool>,
    trigger: Trigger,
    forwarder: Option<thread::JoinHandle<()>>,
    pending: Arc<Pending>,
    read: Option<OwnedFd>,
    cb: DcWatchCallback,
    user: usize,
}

/// Options as JSON. Every field is optional.
#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct OptionsJson {
    /// Deadline per backend in milliseconds (0: wait for completion). Default 150.
    deadline_ms: Option<u64>,
    /// Opt-in: CEC queries.
    #[serde(default)]
    cec: bool,
    /// Opt-in: hardware decode check.
    #[serde(default)]
    decode_check: bool,
    /// What the app will show.
    content: Option<ContentRequest>,
    /// The environment variables the probe reads (`XDG_SESSION_TYPE`, `WAYLAND_DISPLAY`,
    /// `DISPLAY`, `XDG_RUNTIME_DIR`, `SNAP_NAME`); default: the process environment.
    environment: Option<std::collections::BTreeMap<String, String>>,
    /// A watch re-probes by itself every this many milliseconds (default: only when triggered).
    watch_interval_ms: Option<u64>,
    /// App quirk-pack directories.
    #[serde(default)]
    quirk_dirs: Vec<PathBuf>,
    /// App rule-pack directories.
    #[serde(default)]
    rule_dirs: Vec<PathBuf>,
    /// `false` turns redaction off (serials and device names in the clear).
    redact: Option<bool>,
    /// A custom redaction policy.
    redaction: Option<RedactionPolicy>,
}

/// Reads a borrowed C string.
///
/// # Safety
/// `p` must be NULL or a valid NUL-terminated string.
unsafe fn cstr<'a>(p: *const c_char) -> Option<&'a str> {
    if p.is_null() {
        None
    } else {
        // SAFETY: the caller guarantees a valid NUL-terminated string.
        unsafe { CStr::from_ptr(p) }.to_str().ok()
    }
}

fn owned(s: String) -> *mut c_char {
    CString::new(s.replace('\0', " "))
        .map(CString::into_raw)
        .unwrap_or(std::ptr::null_mut())
}

/// One scope field: `"all"` or a list of items.
#[derive(Debug, Deserialize)]
#[serde(untagged)]
enum Sel<T> {
    Word(String),
    List(Vec<T>),
}

impl<T> Sel<T> {
    fn into_selection(self, field: &str) -> Result<Selection<T>, String> {
        match self {
            Sel::Word(w) if w == "all" => Ok(Selection::All),
            Sel::Word(w) => Err(format!(
                "scope.{field}: expected \"all\" or a list, got {w:?}"
            )),
            Sel::List(v) => Ok(Selection::Only(v)),
        }
    }
}

/// Scope as JSON: each field is `"all"` or a list; a missing field means all.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ScopeJson {
    endpoint_classes: Option<Sel<EndpointClass>>,
    endpoints: Option<Sel<EndpointId>>,
    layers: Option<Sel<LayerKind>>,
    fields: Option<Sel<FieldGroup>>,
    presentation_paths: Option<Sel<PresentationPath>>,
}

fn sel<T>(v: Option<Sel<T>>, field: &str) -> Result<Selection<T>, String> {
    v.map_or(Ok(Selection::All), |s| s.into_selection(field))
}

fn parse_scope(s: Option<&str>) -> Result<ProbeScope, String> {
    let Some(t) = s else {
        return Ok(ProbeScope::everything());
    };
    let j: ScopeJson = serde_json::from_str(t).map_err(|e| format!("scope: {e}"))?;
    Ok(ProbeScope {
        endpoint_classes: sel(j.endpoint_classes, "endpoint_classes")?,
        endpoints: sel(j.endpoints, "endpoints")?,
        layers: sel(j.layers, "layers")?,
        fields: sel(j.fields, "fields")?,
        presentation_paths: sel(j.presentation_paths, "presentation_paths")?,
    })
}

fn parse_options(s: Option<&str>) -> Result<ProbeOptions, String> {
    let j: OptionsJson = match s {
        None => OptionsJson::default(),
        Some(t) => serde_json::from_str(t).map_err(|e| format!("options: {e}"))?,
    };
    let mut o = match j.deadline_ms {
        Some(0) => ProbeOptions::unbounded(),
        Some(ms) => ProbeOptions {
            default_deadline: Some(Duration::from_millis(ms)),
            ..ProbeOptions::default()
        },
        None => ProbeOptions::default(),
    };
    if j.cec {
        o = o.with_cec();
    }
    if j.decode_check {
        o = o.with_decode_check();
    }
    if let Some(c) = j.content {
        o = o.with_content(c);
    }
    o.environment = j.environment.map(|m| m.into_iter().collect());
    o.watch_interval = j
        .watch_interval_ms
        .filter(|ms| *ms > 0)
        .map(Duration::from_millis);
    o.quirk_dirs = j.quirk_dirs;
    o.rule_dirs = j.rule_dirs;
    o.redaction = match (j.redaction, j.redact) {
        (Some(p), _) => Some(p),
        (None, Some(false)) => Some(RedactionPolicy::keep_all()),
        _ => None,
    };
    Ok(o)
}

/// The ABI version of the loaded library ([`DC_ABI_VERSION`]).
#[unsafe(no_mangle)]
pub extern "C" fn dc_abi_version() -> u32 {
    DC_ABI_VERSION
}

/// The JSON schema version snapshots follow, e.g. `"1.7.0"` (static string).
#[unsafe(no_mangle)]
pub extern "C" fn dc_schema_version() -> *const c_char {
    static V: std::sync::OnceLock<CString> = std::sync::OnceLock::new();
    V.get_or_init(|| CString::new(displaycaps_model::SCHEMA_VERSION).unwrap_or_default())
        .as_ptr()
}

/// The last error on this thread (empty if none). Valid until the next failing call on the thread.
#[unsafe(no_mangle)]
pub extern "C" fn dc_last_error() -> *const c_char {
    LAST_ERROR.with(|e| e.borrow().as_ptr())
}

/// Frees a string returned by this library. NULL is ignored.
///
/// # Safety
/// `s` must be NULL or a string returned by this library, freed once.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_string_free(s: *mut c_char) {
    if !s.is_null() {
        // SAFETY: `s` came from CString::into_raw in this library.
        drop(unsafe { CString::from_raw(s) });
    }
}

/// A context for the running system. NULL on error.
#[unsafe(no_mangle)]
pub extern "C" fn dc_context_new() -> *mut DcContext {
    match Runtime::new(SystemRoot::Live) {
        Ok(rt) => Box::into_raw(Box::new(DcContext { rt })),
        Err(e) => {
            set_error(e.to_string());
            std::ptr::null_mut()
        }
    }
}

/// A context that replays an extracted capture (`displaycaps import`) instead of the live system.
/// NULL on error.
///
/// # Safety
/// `dir` must be a valid NUL-terminated path.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_context_new_fixture(dir: *const c_char) -> *mut DcContext {
    // SAFETY: forwarded caller guarantee.
    let Some(d) = (unsafe { cstr(dir) }) else {
        set_error("dir is NULL or not UTF-8");
        return std::ptr::null_mut();
    };
    match SystemRoot::fixture(d).and_then(Runtime::new) {
        Ok(rt) => Box::into_raw(Box::new(DcContext { rt })),
        Err(e) => {
            set_error(format!("{d}: {e}"));
            std::ptr::null_mut()
        }
    }
}

/// Frees a context. Snapshots taken from it stay valid. NULL is ignored.
///
/// # Safety
/// `ctx` must be NULL or a context from this library, freed once.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_context_free(ctx: *mut DcContext) {
    if !ctx.is_null() {
        // SAFETY: from Box::into_raw in this library.
        drop(unsafe { Box::from_raw(ctx) });
    }
}

/// Probes `scope_json` (NULL: everything) with `options_json` (NULL: defaults). Returns a snapshot
/// to free with [`dc_snapshot_free`], or NULL on error.
///
/// # Safety
/// `ctx` must be a valid context; the strings NULL or valid NUL-terminated UTF-8.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_probe(
    ctx: *mut DcContext,
    scope_json: *const c_char,
    options_json: *const c_char,
) -> *mut DcSnapshot {
    // SAFETY: caller passes a valid context or NULL.
    let Some(ctx) = (unsafe { ctx.as_ref() }) else {
        set_error("ctx is NULL");
        return std::ptr::null_mut();
    };
    // SAFETY: forwarded caller guarantee.
    let (scope, opts) = unsafe { (cstr(scope_json), cstr(options_json)) };
    let scope = match parse_scope(scope) {
        Ok(s) => s,
        Err(e) => {
            set_error(e);
            return std::ptr::null_mut();
        }
    };
    let opts = match parse_options(opts) {
        Ok(o) => o,
        Err(e) => {
            set_error(e);
            return std::ptr::null_mut();
        }
    };
    Box::into_raw(Box::new(DcSnapshot::new(ctx.rt.probe(&scope, &opts))))
}

/// A second handle to the same snapshot (cheap). Free both.
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_snapshot_clone(snap: *const DcSnapshot) -> *mut DcSnapshot {
    // SAFETY: caller passes a valid snapshot or NULL.
    match unsafe { snap.as_ref() } {
        Some(s) => Box::into_raw(Box::new(DcSnapshot::new(s.snap.clone()))),
        None => {
            set_error("snapshot is NULL");
            std::ptr::null_mut()
        }
    }
}

/// Frees a snapshot. NULL is ignored.
///
/// # Safety
/// `snap` must be NULL or a snapshot from this library, freed once.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_snapshot_free(snap: *mut DcSnapshot) {
    if !snap.is_null() {
        // SAFETY: from Box::into_raw in this library.
        drop(unsafe { Box::from_raw(snap) });
    }
}

/// The snapshot's generation (increases with each probe of the context).
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_snapshot_generation(snap: *const DcSnapshot) -> u64 {
    // SAFETY: caller passes a valid snapshot or NULL.
    unsafe { snap.as_ref() }.map_or(0, |s| s.snap.generation)
}

/// The whole snapshot as JSON (owned; free with [`dc_string_free`]).
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_snapshot_json(snap: *const DcSnapshot) -> *mut c_char {
    // SAFETY: caller passes a valid snapshot or NULL.
    match unsafe { snap.as_ref() } {
        Some(s) => owned(serde_json::to_string(&*s.snap).unwrap_or_default()),
        None => {
            set_error("snapshot is NULL");
            std::ptr::null_mut()
        }
    }
}

/// Number of endpoints in the snapshot.
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_snapshot_endpoint_count(snap: *const DcSnapshot) -> usize {
    // SAFETY: caller passes a valid snapshot or NULL.
    unsafe { snap.as_ref() }.map_or(0, |s| s.ids.len())
}

/// The id of endpoint `index` (borrowed from the snapshot), or NULL past the end.
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_snapshot_endpoint_id(
    snap: *const DcSnapshot,
    index: usize,
) -> *const c_char {
    // SAFETY: caller passes a valid snapshot or NULL.
    unsafe { snap.as_ref() }
        .and_then(|s| s.ids.get(index))
        .map_or(std::ptr::null(), |c| c.as_ptr())
}

/// One endpoint as JSON (owned), or NULL if the id isn't in the snapshot.
///
/// # Safety
/// `snap` must be a valid snapshot; `id` a valid NUL-terminated string.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_snapshot_endpoint_json(
    snap: *const DcSnapshot,
    id: *const c_char,
) -> *mut c_char {
    // SAFETY: caller guarantees.
    let (Some(s), Some(id)) = (unsafe { snap.as_ref() }, unsafe { cstr(id) }) else {
        set_error("snapshot or id is NULL");
        return std::ptr::null_mut();
    };
    match s.snap.endpoints.iter().find(|e| e.id.0 == id) {
        Some(e) => owned(serde_json::to_string(e).unwrap_or_default()),
        None => {
            set_error(format!("no endpoint {id}"));
            std::ptr::null_mut()
        }
    }
}

/// The findings as a JSON array (owned).
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_snapshot_findings_json(snap: *const DcSnapshot) -> *mut c_char {
    // SAFETY: caller passes a valid snapshot or NULL.
    match unsafe { snap.as_ref() } {
        Some(s) => owned(serde_json::to_string(&s.snap.findings).unwrap_or_default()),
        None => {
            set_error("snapshot is NULL");
            std::ptr::null_mut()
        }
    }
}

/// Watches `scope_json` with `options_json` and delivers each new snapshot with its diff to `cb`.
/// The first delivery is the initial snapshot. `mode` is [`DC_WATCH_THREAD`] or
/// [`DC_WATCH_DISPATCH`]. Returns a watch to free with [`dc_watch_free`], or NULL on error.
///
/// # Safety
/// `ctx` must be a valid context; strings NULL or valid; `cb` valid for the watch's lifetime and,
/// in thread mode, callable from another thread with `user`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_watch_new(
    ctx: *mut DcContext,
    scope_json: *const c_char,
    options_json: *const c_char,
    mode: u32,
    cb: DcWatchCallback,
    user: *mut c_void,
) -> *mut DcWatch {
    // SAFETY: caller guarantees.
    let Some(ctx) = (unsafe { ctx.as_ref() }) else {
        set_error("ctx is NULL");
        return std::ptr::null_mut();
    };
    if cb.is_none() {
        set_error("callback is NULL");
        return std::ptr::null_mut();
    }
    // SAFETY: forwarded caller guarantee.
    let (scope, opts) = unsafe { (cstr(scope_json), cstr(options_json)) };
    let (scope, opts) = match (parse_scope(scope), parse_options(opts)) {
        (Ok(s), Ok(o)) => (s, o),
        (Err(e), _) | (_, Err(e)) => {
            set_error(e);
            return std::ptr::null_mut();
        }
    };
    let watch = match ctx.rt.watch(&scope, &opts) {
        Ok(w) => w,
        Err(e) => {
            set_error(e.to_string());
            return std::ptr::null_mut();
        }
    };
    if mode != DC_WATCH_THREAD && mode != DC_WATCH_DISPATCH {
        set_error(format!("unknown watch mode {mode}"));
        return std::ptr::null_mut();
    }
    let trigger = watch.trigger_handle();
    let stop = Arc::new(AtomicBool::new(false));
    let pending = Arc::new(Pending {
        queue: Mutex::new(VecDeque::new()),
    });
    let (read, write) = if mode == DC_WATCH_DISPATCH {
        match nix::unistd::pipe2(nix::fcntl::OFlag::O_NONBLOCK | nix::fcntl::OFlag::O_CLOEXEC) {
            Ok((r, w)) => (Some(r), Some(w)),
            Err(e) => {
                set_error(format!("pipe: {e}"));
                return std::ptr::null_mut();
            }
        }
    } else {
        (None, None)
    };
    let user_addr = user as usize;
    let st = stop.clone();
    let pq = pending.clone();
    let forwarder = thread::Builder::new()
        .name("displaycaps-events".into())
        .spawn(move || {
            while !st.load(Ordering::SeqCst) {
                let Some(ev) = watch.recv_timeout(Duration::from_millis(100)) else {
                    continue;
                };
                let diff = CString::new(serde_json::to_string(&ev.diff).unwrap_or_default())
                    .unwrap_or_default();
                match &write {
                    Some(w) => {
                        let mut q = pq.queue.lock().unwrap_or_else(|e| e.into_inner());
                        // An app that stops dispatching keeps at most MAX_PENDING updates; the
                        // oldest go first (each diff names its from/to generations).
                        while q.len() >= MAX_PENDING {
                            q.pop_front();
                        }
                        q.push_back((ev.snapshot, diff));
                        drop(q);
                        let _ = nix::unistd::write(w, &[1u8]);
                    }
                    None => {
                        let s = DcSnapshot::new(ev.snapshot);
                        if let Some(f) = cb {
                            // SAFETY: the caller made `cb` and `user` valid for this thread.
                            unsafe { f(user_addr as *mut c_void, &s, diff.as_ptr()) };
                        }
                    }
                }
            }
            drop(watch);
        });
    let forwarder = match forwarder {
        Ok(h) => h,
        Err(e) => {
            set_error(e.to_string());
            return std::ptr::null_mut();
        }
    };
    Box::into_raw(Box::new(DcWatch {
        stop,
        trigger,
        forwarder: Some(forwarder),
        pending,
        read,
        cb,
        user: user_addr,
    }))
}

/// Asks the watch to re-probe its scope now. An update is delivered only if something in scope
/// changed. NULL is ignored.
///
/// # Safety
/// `w` must be NULL or a valid watch.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_watch_trigger(w: *const DcWatch) {
    // SAFETY: caller passes a valid watch or NULL.
    if let Some(w) = unsafe { w.as_ref() } {
        w.trigger.fire();
    }
}

/// The fd to poll for readability in dispatch mode (-1 in thread mode).
///
/// # Safety
/// `w` must be a valid watch.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_watch_fd(w: *const DcWatch) -> c_int {
    // SAFETY: caller passes a valid watch or NULL.
    unsafe { w.as_ref() }
        .and_then(|w| w.read.as_ref())
        .map_or(-1, |fd| fd.as_raw_fd())
}

/// In dispatch mode, delivers every pending update to the callback on this thread. Returns how
/// many were delivered (0 in thread mode).
///
/// # Safety
/// `w` must be a valid watch; call from one thread at a time.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_watch_dispatch(w: *mut DcWatch) -> c_int {
    // SAFETY: caller passes a valid watch or NULL.
    let Some(w) = (unsafe { w.as_ref() }) else {
        return 0;
    };
    let Some(read) = &w.read else { return 0 };
    let mut buf = [0u8; 64];
    while matches!(nix::unistd::read(read, &mut buf), Ok(n) if n > 0) {}
    let items: Vec<_> = w
        .pending
        .queue
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .drain(..)
        .collect();
    let n = items.len();
    for (snap, diff) in items {
        let s = DcSnapshot::new(snap);
        if let Some(f) = w.cb {
            // SAFETY: the caller made `cb` and `user` valid.
            unsafe { f(w.user as *mut c_void, &s, diff.as_ptr()) };
        }
    }
    c_int::try_from(n).unwrap_or(c_int::MAX)
}

/// Stops and frees a watch. Waits for a running callback to return and for an in-flight
/// re-probe to finish (bounded by the probe deadlines; unbounded with `"deadline_ms": 0`), so
/// free a watch with deadlines off a UI thread. NULL is ignored.
///
/// # Safety
/// `w` must be NULL or a watch from this library, freed once, not from inside its callback.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn dc_watch_free(w: *mut DcWatch) {
    if w.is_null() {
        return;
    }
    // SAFETY: from Box::into_raw in this library.
    let mut w = unsafe { Box::from_raw(w) };
    w.stop.store(true, Ordering::SeqCst);
    if let Some(h) = w.forwarder.take() {
        let _ = h.join();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::AtomicUsize;

    #[test]
    fn options_parse() {
        assert!(parse_options(None).unwrap().default_deadline.is_some());
        let o = parse_options(Some(r#"{"deadline_ms":0,"cec":true,"redact":false}"#)).unwrap();
        assert!(o.cec && o.default_deadline.is_none());
        assert_eq!(o.redaction, Some(RedactionPolicy::keep_all()));
        let o = parse_options(Some(
            r#"{"environment":{"DISPLAY":":0"},"watch_interval_ms":250,"decode_check":true}"#,
        ))
        .unwrap();
        assert_eq!(
            o.environment,
            Some(vec![("DISPLAY".to_string(), ":0".to_string())])
        );
        assert_eq!(o.watch_interval, Some(Duration::from_millis(250)));
        assert!(o.decode_check && !o.cec);
        assert!(parse_options(Some(r#"{"nope":1}"#)).is_err());
        assert_eq!(parse_scope(Some("{}")).unwrap(), ProbeScope::everything());
        let s = parse_scope(Some(
            r#"{"endpoint_classes":["external"],"fields":["effective"],"presentation_paths":["direct_kms"]}"#,
        ))
        .unwrap();
        assert!(
            s.fields.includes(&FieldGroup::Effective) && !s.fields.includes(&FieldGroup::Findings)
        );
        assert!(s.presentation_paths.includes(&PresentationPath::DirectKms));
        assert!(parse_scope(Some(r#"{"layers":"some"}"#)).is_err());
        assert!(parse_scope(Some(r#"{"directions":["playback"]}"#)).is_err());
    }

    fn c(s: &str) -> CString {
        CString::new(s).unwrap()
    }

    fn fixture(name: &str) -> PathBuf {
        let dir =
            std::env::temp_dir().join(format!("displaycaps-ffi-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("root/etc")).unwrap();
        std::fs::write(
            dir.join("manifest.json"),
            r#"{"format":1,"tool_version":"t","captured_at_ms":5,"file_count":1,"commands":[],"redaction":[]}"#,
        )
        .unwrap();
        std::fs::write(dir.join("root/etc/os-release"), "ID=debian\n").unwrap();
        dir
    }

    fn take(p: *mut c_char) -> String {
        assert!(!p.is_null(), "{:?}", unsafe {
            CStr::from_ptr(dc_last_error())
        });
        // SAFETY: `p` is a string this library returned.
        let s = unsafe { CStr::from_ptr(p) }.to_string_lossy().into_owned();
        unsafe { dc_string_free(p) };
        s
    }

    #[test]
    fn versions_and_errors() {
        assert_eq!(dc_abi_version(), DC_ABI_VERSION);
        // SAFETY: a static NUL-terminated string.
        let v = unsafe { CStr::from_ptr(dc_schema_version()) }
            .to_str()
            .unwrap();
        assert_eq!(v, displaycaps_model::SCHEMA_VERSION);
        // SAFETY: NULL arguments are part of the contract.
        unsafe {
            assert!(dc_probe(std::ptr::null_mut(), std::ptr::null(), std::ptr::null()).is_null());
            assert_eq!(
                CStr::from_ptr(dc_last_error()).to_str().unwrap(),
                "ctx is NULL"
            );
            assert!(dc_context_new_fixture(std::ptr::null()).is_null());
            assert!(dc_context_new_fixture(c("/nonexistent/fixture").as_ptr()).is_null());
            dc_string_free(std::ptr::null_mut());
            dc_snapshot_free(std::ptr::null_mut());
            dc_watch_free(std::ptr::null_mut());
            dc_watch_trigger(std::ptr::null());
        }
    }

    #[test]
    fn probe_a_fixture_through_the_c_api() {
        let dir = fixture("probe");
        let path = c(dir.to_str().unwrap());
        // SAFETY: valid strings and handles throughout; every handle is freed once.
        unsafe {
            let ctx = dc_context_new_fixture(path.as_ptr());
            assert!(!ctx.is_null());
            let scope = c(r#"{"layers":["environment"],"endpoint_classes":[],"fields":[]}"#);
            let opts = c(r#"{"deadline_ms":0}"#);
            let snap = dc_probe(ctx, scope.as_ptr(), opts.as_ptr());
            assert!(!snap.is_null());
            assert_eq!(dc_snapshot_generation(snap), 1);
            assert_eq!(dc_snapshot_endpoint_count(snap), 0);
            assert!(dc_snapshot_endpoint_id(snap, 0).is_null());
            let j: serde_json::Value = serde_json::from_str(&take(dc_snapshot_json(snap))).unwrap();
            assert_eq!(j["layers"].as_array().unwrap().len(), 1);
            assert_eq!(j["environment"]["os"]["value"]["id"], "debian");
            assert_eq!(j["source"]["kind"], "fixture");
            assert_eq!(take(dc_snapshot_findings_json(snap)), "[]");
            assert!(dc_snapshot_endpoint_json(snap, c("none").as_ptr()).is_null());
            let again = dc_snapshot_clone(snap);
            assert_eq!(dc_snapshot_generation(again), 1);
            dc_snapshot_free(again);
            dc_snapshot_free(snap);
            let bad = c(r#"{"layers":"some"}"#);
            assert!(dc_probe(ctx, bad.as_ptr(), std::ptr::null()).is_null());
            assert!(
                CStr::from_ptr(dc_last_error())
                    .to_str()
                    .unwrap()
                    .contains("scope.layers")
            );
            dc_context_free(ctx);
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

    unsafe extern "C" fn count(user: *mut c_void, snap: *const DcSnapshot, diff: *const c_char) {
        // SAFETY: the tests pass a live AtomicUsize and the library passes valid pointers.
        let n = unsafe { &*(user as *const AtomicUsize) };
        assert!(unsafe { dc_snapshot_generation(snap) } > 0);
        assert!(
            unsafe { CStr::from_ptr(diff) }
                .to_str()
                .unwrap()
                .contains("to_generation")
        );
        n.fetch_add(1, Ordering::SeqCst);
    }

    fn wait_for(n: &AtomicUsize, want: usize, mut tick: impl FnMut()) {
        let until = std::time::Instant::now() + Duration::from_secs(5);
        while n.load(Ordering::SeqCst) < want {
            assert!(
                std::time::Instant::now() < until,
                "timed out at {}",
                n.load(Ordering::SeqCst)
            );
            tick();
            thread::sleep(Duration::from_millis(5));
        }
    }

    #[test]
    fn watch_on_a_thread_and_by_fd() {
        let dir = fixture("watch");
        let path = c(dir.to_str().unwrap());
        let scope = c(r#"{"layers":["environment"],"endpoint_classes":[],"fields":[]}"#);
        let calls = AtomicUsize::new(0);
        let user = &calls as *const AtomicUsize as *mut c_void;
        // SAFETY: valid strings and handles; `calls` outlives both watches.
        unsafe {
            let ctx = dc_context_new_fixture(path.as_ptr());
            // Thread mode: the callback runs on the library's thread, and there is no fd.
            let w = dc_watch_new(
                ctx,
                scope.as_ptr(),
                std::ptr::null(),
                DC_WATCH_THREAD,
                Some(count),
                user,
            );
            assert!(!w.is_null());
            assert_eq!(dc_watch_fd(w), -1);
            wait_for(&calls, 1, || {});
            // The os-release changes, then the app triggers a re-probe.
            std::fs::write(dir.join("root/etc/os-release"), "ID=ubuntu\n").unwrap();
            dc_watch_trigger(w);
            wait_for(&calls, 2, || {});
            dc_watch_free(w);

            // Dispatch mode: updates wait for the app's own thread.
            calls.store(0, Ordering::SeqCst);
            let w = dc_watch_new(
                ctx,
                scope.as_ptr(),
                std::ptr::null(),
                DC_WATCH_DISPATCH,
                Some(count),
                user,
            );
            assert!(!w.is_null());
            assert!(dc_watch_fd(w) >= 0);
            wait_for(&calls, 1, || {
                dc_watch_dispatch(w);
            });
            dc_watch_free(w);
            // Bad mode and missing callback are errors.
            assert!(
                dc_watch_new(ctx, scope.as_ptr(), std::ptr::null(), 7, Some(count), user).is_null()
            );
            assert!(
                dc_watch_new(
                    ctx,
                    scope.as_ptr(),
                    std::ptr::null(),
                    DC_WATCH_THREAD,
                    None,
                    user
                )
                .is_null()
            );
            dc_context_free(ctx);
        }
        let _ = std::fs::remove_dir_all(&dir);
    }
}
